describe("sympy/printing/tests/test_tableform.py", () => {
  it("test_TableForm:54", () => {
    expect(() => new TableForm([[rational(5), rational(7)], [rational(4), rational(2)], [rational(10), rational(3)]], { headings: [['Group A', 'Group B', 'Group C'], ['y1', 'y2']], alignments: 'middle' })).toThrow(RangeError);
  });
  it("test_TableForm:75", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new TableForm([[rational(1), rational(100)], [rational(100), rational(1)]], { headings: [['xxx', 'x'], null], alignments: 'l' }))).toBe('xxx | 1   100\n  x | 100 1  ');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("test_TableForm:80", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new TableForm([[rational(1), rational(100)], [rational(100), rational(1)]], { headings: [['xxx', 'x'], null], alignments: 'lr' }))).toBe('xxx | 1   100\n  x | 100   1');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("test_TableForm:84", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new TableForm([[rational(1), rational(100)], [rational(100), rational(1)]], { headings: [['xxx', 'x'], null], alignments: 'clr' }))).toBe('xxx | 1   100\n x  | 100   1');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("test_TableForm:89", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(pyStr(new TableForm([[rational(1), rational(100)], [rational(100), rational(1)]], { headings: [['xxx', 'x'], null] }))).toBe('xxx | 1   100\n  x | 100 1  ');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("test_TableForm:94", () => {
    expect(() => new TableForm([[rational(1), rational(100)], [rational(100), rational(1)]], { alignments: 'clr' })).toThrow(RangeError);
  });
});
